{
  "technical_and_design_decisions": [
    "Use Go programming language, standard for Hyperledger Fabric.",
    "Use Protocol Buffers for message serialization, relying on existing Fabric protobuf definitions.",
    "For U1, modify core Fabric peer code: chaincode execution, endorsement, and validation modules to include and compare read set values.",
    "For U2–U8, implement a separate Go package that imports Fabric protos and uses copied types from genesisconfig to avoid viper/yaml dependencies.",
    "Signature operations use the Fabric crypto provider interface (bccsp) with key material passed as input.",
    "ConfigUpdate computation implements a diff algorithm using protobuf reflection, similar to configtxlator compute_update.",
    "ChannelConfig transactions are encoded using existing Fabric common/configtx package where applicable."
  ],
  "assumptions": [
    "The developer has deep knowledge of Hyperledger Fabric internals and access to the source code.",
    "The existing codebase is based on a recent release (e.g., v2.x) and follows the same structure.",
    "All tests are executed in a simulated environment without a real network.",
    "For U1, backward compatibility is maintained by ignoring missing read set values in older transactions.",
    "The library for U2–U8 is implemented as a new Go module within the Fabric codebase.",
    "Effort estimates assume a single experienced developer working without external interruptions.",
    "Testing includes automated unit tests and integration tests that compare outputs with existing tools.",
    "Documentation includes inline code comments and a README."
  ],
  "activities": [
    {
      "activity_id": "A0",
      "activity_name": "Requirement analysis and overall design",
      "activity_description": "Review all user stories, define architecture, plan integration points, and identify shared components.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A1",
      "activity_name": "Project setup and common infrastructure",
      "activity_description": "Set up Go module, import Fabric protos, copy necessary types from genesisconfig, create shared utility functions for proto encoding/decoding.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Modify protobuf definition for read set (U1)",
      "activity_description": "Extend the read set protobuf message (e.g., chaincode.proto) to include optional value fields alongside keys and versions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Modify chaincode execution to capture read values (U1)",
      "activity_description": "Update chaincode stub and container logic to record the values of keys read during GetState, GetStateByRange, etc., into the read set.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Modify endorsement logic to include read set values (U1)",
      "activity_description": "Update the endorser to include the new value fields in the read set when building the proposal response.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Modify validation logic to compare read set values (U1)",
      "activity_description": "Update the validation system chaincode (vscc) to compare the values in the read set with the local world state, rejecting transactions on mismatch.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2.5",
      "activity_name": "Unit and integration testing for read set tampering (U1)",
      "activity_description": "Write unit tests for each modified component and an integration test that verifies transaction invalidation when world state is tampered.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2.6",
      "activity_name": "Documentation for U1 changes",
      "activity_description": "Update developer documentation, release notes, and add comments describing the new read set behavior.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement CreateChannelTx function (U2)",
      "activity_description": "Design and implement the CreateChannelTx function that generates a proto-encoded genesis block from a Profile struct, including copying necessary types and handling options.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement SignChannelUpdate function (U3)",
      "activity_description": "Implement a function that signs a ChannelUpdate transaction using provided key material and returns a detached signature.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement AssembleSignedConfigUpdate function (U4)",
      "activity_description": "Implement a function that takes a ConfigUpdate transaction and a collection of detached signatures and produces a fully signed channel config update transaction.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement batch size config update function (U5)",
      "activity_description": "Implement a function that generates an unsigned channel update transaction to modify the max_message_count batch size parameter.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement GenerateOrgConfigGroup function (U6)",
      "activity_description": "Implement a function that creates a ConfigGroup representing an Organization from provided cryptographic material (MSP).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement ComputeConfigUpdate function (U7)",
      "activity_description": "Implement a function that computes the ConfigUpdate diff between a base and modified configuration using protobuf reflection.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement AddOrgToConsortiumUpdate function (U8)",
      "activity_description": "Implement a function that generates an unsigned channel update transaction to add an organization to a named consortium in the system channel.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A10",
      "activity_name": "Library integration testing (U2–U8)",
      "activity_description": "Write end-to-end integration tests that compare outputs of the library functions with those produced by existing tools (configtxgen, configtxlator, etc.) to ensure semantic equivalence.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A11",
      "activity_name": "Library documentation",
      "activity_description": "Write user-facing documentation (API docs, usage examples) for all library functions implemented in U2–U8.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A12",
      "activity_name": "Code review and refactoring",
      "activity_description": "Perform code review of all components, refactor as needed, and ensure consistency across the library and core changes.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 430
  }
}

